package com.combatxptracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * The attack timer: ticks until your next attack, above your character while fighting.
 */
class AttackTimerOverlay extends Overlay
{
	private static final Color READY = new Color(0x3C, 0xE6, 0x5A);
	private static final int HEIGHT_ABOVE_HEAD = 40;

	private final Client client;
	private final CombatXpTrackerPlugin plugin;
	private final CombatXpTrackerConfig config;
	private Font font;

	@Inject
	AttackTimerOverlay(Client client, CombatXpTrackerPlugin plugin, CombatXpTrackerConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.attackTimer())
		{
			return null;
		}
		int ticks = plugin.getTicksUntilAttack();
		Player player = client.getLocalPlayer();
		if (ticks < 0 || player == null)
		{
			return null;
		}

		if (font == null)
		{
			font = FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 18f);
		}
		graphics.setFont(font);
		String text = String.valueOf(ticks);
		Point location = player.getCanvasTextLocation(graphics, text, player.getLogicalHeight() + HEIGHT_ABOVE_HEAD);
		if (location != null)
		{
			OverlayUtil.renderTextLocation(graphics, location, text, ticks == 0 ? READY : config.attackTimerColour());
		}
		return null;
	}
}

