 */
public enum XpRateMode
{
	/** The last few seconds of XP drops (the "averaging window" setting). Reacts fast. */
	RECENT("Recent (averaging window)"),
	/** All XP this session divided by time spent training, breaks excluded. Smooth. */
	SESSION("Whole session");

