package com.combatxptracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import org.junit.Test;

/**
 * Activity time, whole-session XP/hr, and the copied session summary.
 */
public class SessionFeaturesTest
{
	private static final long MINUTE = 60_000L;

	@Test
	public void activityTimerSkipsBreaks()
	{
		ActivityTimer timer = new ActivityTimer();
		timer.mark(0);
		timer.mark(2 * MINUTE);
		// A 10-minute gap is a break and isn't counted.
		timer.mark(12 * MINUTE);
		timer.mark(15 * MINUTE);
		assertEquals(5 * MINUTE, timer.getActiveMillis());
		// Exactly the 5-minute limit still counts.
		timer.mark(20 * MINUTE);
		assertEquals(10 * MINUTE, timer.getActiveMillis());
	}

	@Test
	public void perHourNeedsAMinute()
	{
		assertEquals(-1, ActivityTimer.perHour(10, 59_999), 0.0);
		assertEquals(600, ActivityTimer.perHour(10, MINUTE), 1e-9);
	}

	@Test
	public void wholeSessionXpPerHourIgnoresBreaks()
	{
		SkillProgress p = new SkillProgress();
		p.resetBaseline(0, 0);
		// 1,000 xp every minute for 10 minutes...
		for (int i = 1; i <= 10; i++)
		{
			p.recordXp(i * 1_000, i * MINUTE, 300);
		}
		// ...an hour's break, then 1,000 xp a minute after coming back.
		p.recordXp(11_000, 70 * MINUTE, 300);
		p.recordXp(12_000, 71 * MINUTE, 300);

		// 12,000 xp over 10 minutes of training (the first drop only starts the clock,
		// and the break isn't counted): 72,000 xp/hr
		assertEquals(10 * 1_000 + 2_000, p.getSessionXpGained());
		assertEquals(72_000, p.getSessionXpPerHour());
		assertEquals(72_000, p.getXpPerHour(XpRateMode.SESSION));
		// The recent-window rate only sees the last minute: 60,000 xp/hr
		assertEquals(60_000, p.getXpPerHour(XpRateMode.RECENT));
	}

	@Test
	public void timeToGoalUsesTheChosenRate()
	{
		SkillProgress p = new SkillProgress();
		int start = Experience.getXpForLevel(98);
		p.resetBaseline(start, 0);
		p.setGoal(Goal.ofLevel(99), start);
		for (int i = 1; i <= 60; i++)
		{
			p.recordXp(start + i * 1_000, i * MINUTE, 30);
		}
		int sessionRate = p.getXpPerHour(XpRateMode.SESSION);
		assertTrue(sessionRate > 0);
		assertEquals(p.getXpRemainingToGoal() / (double) sessionRate, p.getEstimatedHoursToGoal(XpRateMode.SESSION), 1e-9);
	}

	@Test
	public void summaryListsXpCombatMonstersAndGoals()
	{
		Map<Skill, SkillProgress> skills = new EnumMap<>(Skill.class);
		SkillProgress attack = new SkillProgress();
		attack.resetBaseline(Experience.getXpForLevel(80), 0);
		attack.setGoal(Goal.ofLevel(99), Experience.getXpForLevel(80));
		attack.recordXp(Experience.getXpForLevel(80) + 50_000, MINUTE, 30);
		skills.put(Skill.ATTACK, attack);
		skills.put(Skill.COOKING, new SkillProgress());

		HitStats hits = new HitStats();
		hits.recordHit(40);
		hits.recordHit(20);

		MonsterTracker monsters = new MonsterTracker();
		monsters.recordHit("Abyssal demon", 45, CombatStyle.MELEE, 0);
		monsters.recordKill("Abyssal demon", 0);
		monsters.recordLoot("Abyssal demon", Collections.singletonList(
			new MonsterTracker.Drop(4151, "Abyssal whip", 1, 1_500_000)), 0);

		String text = SessionSummaryText.build(skills, hits, monsters.snapshot(), XpRateMode.RECENT);
		assertTrue(text, text.startsWith("Combat & XP Tracker - session summary"));
		assertTrue(text, text.contains("XP gained: +50,000"));
		assertTrue(text, text.contains("Attack +50,000"));
		assertFalse(text, text.contains("Cooking"));
		assertTrue(text, text.contains("Hits: 2 | Average: 30.0 | Biggest: 40"));
		assertTrue(text, text.contains("Kills: 1 | Loot: 1.5M gp"));
		assertTrue(text, text.contains("Abyssal demon - 1 kill, 1.5M gp, biggest hit 45 (Melee)"));
		assertTrue(text, text.contains("Attack: "));
		assertTrue(text, text.contains("to Level 99"));
	}

	@Test
	public void summaryOnlyListsTheTopMonsters()
	{
		MonsterTracker monsters = new MonsterTracker();
		for (int i = 0; i < 8; i++)
		{
			monsters.recordKill("Monster " + i, i);
		}
		String text = SessionSummaryText.build(new EnumMap<>(Skill.class), new HitStats(), monsters.snapshot(), XpRateMode.RECENT);
		assertTrue(text, text.contains("...and 3 more"));
	}
}

package com.combatxptracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import net.runelite.api.Experience;
import org.junit.Test;

public class SkillProgressTest
{
	private static final int WINDOW_SECONDS = 300;

	@Test
	public void xpPerHourFromTwoSamples()
	{
		SkillProgress p = new SkillProgress();
		p.resetBaseline(1_000_000, 0);
		p.recordXp(1_001_000, 60_000, WINDOW_SECONDS);
		// 1,000 xp in one minute = 60,000 xp/hr
		assertEquals(60_000, p.getXpPerHour());
	}

	@Test
	public void noRateWithoutTwoSamples()
	{
		SkillProgress p = new SkillProgress();
		assertEquals(0, p.getXpPerHour());
		p.resetBaseline(500, 0);
		assertEquals(0, p.getXpPerHour());
		assertEquals(-1, p.getEstimatedHoursToGoal(), 0.0);
	}

	@Test
	public void oldSamplesFallOutOfTheWindow()
	{
		SkillProgress p = new SkillProgress();
		p.resetBaseline(0, 0);
		p.recordXp(10_000, 10_000, 30);
		// A burst of 10k at the start; 60s later only this window's gains count.
		p.recordXp(10_100, 60_000, 30);
		p.recordXp(10_200, 70_000, 30);
		// Window is now [60s..70s]: 100 xp in 10 seconds = 36,000 xp/hr
		assertEquals(36_000, p.getXpPerHour());
	}

	/**
	 * Regression test for the 1.3.x bug: progress was measured from the start of the
	 * current level, so the bar dropped to ~0% on every level-up.
	 */
	@Test
	public void progressNeverGoesBackwardsAcrossLevelUps()
	{
		SkillProgress p = new SkillProgress();
		int start = Experience.getXpForLevel(70) + 1_000;
		p.resetBaseline(start, 0);
		p.setGoal(Goal.ofLevel(99), start);

		double previous = p.getProgressToGoal();
		assertEquals(0.0, previous, 1e-9);

		long t = 0;
		for (int xp = start; xp <= Experience.getXpForLevel(80); xp += 25_000)
		{
			t += 1_000;
			p.recordXp(xp, t, WINDOW_SECONDS);
			double now = p.getProgressToGoal();
			assertTrue("progress went backwards at " + xp + " xp", now >= previous);
			previous = now;
		}
		assertTrue(previous > 0.0);
	}

	@Test
	public void progressIsMeasuredFromTheGoalStart()
	{
		int target = Experience.getXpForLevel(99);
		// Halfway between the start and the goal.
		int start = 1_000_000;
		int halfway = start + (target - start) / 2;
		assertEquals(0.5, SkillProgress.progress(halfway, start, target), 1e-6);
		assertEquals(0.0, SkillProgress.progress(start, start, target), 1e-9);
		assertEquals(1.0, SkillProgress.progress(target, start, target), 1e-9);
		assertEquals(1.0, SkillProgress.progress(target + 5, start, target), 1e-9);
	}

	@Test
	public void goalsPast99WorkUpTo200m()
	{
		SkillProgress p = new SkillProgress();
		int xp = 100_000_000;
		p.resetBaseline(xp, 0);
		p.setGoal(Goal.ofXp(200_000_000), xp);
		assertEquals(0.0, p.getProgressToGoal(), 1e-9);
		assertEquals(100_000_000, p.getXpRemainingToGoal());
		// Virtual level, not capped at 99.
		assertEquals(Experience.getLevelForXp(xp), p.getCurrentLevel());
		assertTrue(p.getCurrentLevel() > 99);

		// 50M over an hour in 200K drops (one huge jump would be rejected as impossible).
		for (int i = 1; i <= 250; i++)
		{
			p.recordXp(100_000_000 + i * 200_000, i * 14_400L, 7200);
		}
		assertEquals(0.5, p.getProgressToGoal(), 1e-9);
		// 50M in an hour -> 1 more hour to go
		assertEquals(1.0, p.getEstimatedHoursToGoal(), 1e-9);
	}

	@Test
	public void goalReached()
	{
		SkillProgress p = new SkillProgress();
		p.resetBaseline(Experience.getXpForLevel(98), 0);
		p.setGoal(Goal.ofLevel(99), Experience.getXpForLevel(98));
		assertFalse(p.isGoalReached());
		p.recordXp(Experience.getXpForLevel(99), 1_000, WINDOW_SECONDS);
		assertTrue(p.isGoalReached());
		assertEquals(1.0, p.getProgressToGoal(), 1e-9);
		assertEquals(0, p.getXpRemainingToGoal());
	}

	@Test
	public void unknownStartFallsBackToCurrentLevel()
	{
		// Goals saved by 1.3.x have no start XP until the plugin fills one in.
		int levelStart = Experience.getXpForLevel(50);
		int target = Experience.getXpForLevel(51);
		assertEquals(0.0, SkillProgress.progress(levelStart, -1, target), 1e-9);
	}

	@Test
	public void sessionGainCountsFromFirstBaseline()
	{
		SkillProgress p = new SkillProgress();
		p.resetBaseline(1_000, 0);
		p.recordXp(1_500, 1_000, WINDOW_SECONDS);
		// A relog re-baselines but must not restart the session count.
		p.reset();
		p.resetBaseline(1_500, 5_000);
		p.recordXp(1_800, 6_000, WINDOW_SECONDS);
		assertEquals(800, p.getSessionXpGained());

		p.resetSession();
		assertEquals(0, p.getSessionXpGained());
	}
}

package com.combatxptracker;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class SlayerTaskMatcherTest
{
	@Test
	public void pluralTaskMatchesSingularNpc()
	{
		assertTrue(SlayerTaskMatcher.matches("Abyssal demons", "Abyssal demon"));
		assertTrue(SlayerTaskMatcher.matches("Black dragons", "Black dragon"));
		assertTrue(SlayerTaskMatcher.matches("Wolves", "Wolf"));
		assertTrue(SlayerTaskMatcher.matches("Harpie bug swarms", "Harpie bug swarm"));
		assertTrue(SlayerTaskMatcher.matches("Hellhounds", "Hellhound"));
	}

	@Test
	public void variantNamesStillMatch()
	{
		assertTrue(SlayerTaskMatcher.matches("Abyssal demons", "Greater abyssal demon"));
		assertTrue(SlayerTaskMatcher.matches("Greater demons", "Greater demon"));
		assertTrue(SlayerTaskMatcher.matches("Kalphite", "Kalphite Soldier"));
		assertTrue(SlayerTaskMatcher.matches("Zulrah", "Zulrah"));
	}

	@Test
	public void ignoresCaseTagsAndNonBreakingSpaces()
	{
		assertTrue(SlayerTaskMatcher.matches("ABYSSAL DEMONS", "<col=ffff00>Abyssal demon</col>"));
	}

	@Test
	public void differentMonstersDontMatch()
	{
		assertFalse(SlayerTaskMatcher.matches("Black demons", "Greater demon"));
		assertFalse(SlayerTaskMatcher.matches("Black dragons", "Blue dragon"));
		// Whole words only: "Rat" is not part of "Pirate".
		assertFalse(SlayerTaskMatcher.matches("Rats", "Pirate"));
	}

	@Test
	public void noTaskOrTargetNeverMatches()
	{
		assertFalse(SlayerTaskMatcher.matches(null, "Abyssal demon"));
		assertFalse(SlayerTaskMatcher.matches("Abyssal demons", null));
		assertFalse(SlayerTaskMatcher.matches("  ", "Abyssal demon"));
	}
}
